INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=2,1,0) FROM information_schema.tables WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('operations_audit','operations_file_delivery') AND table_type='BASE TABLE' AND engine='InnoDB';
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.columns c LEFT JOIN compact_operations_columns e ON e.table_name=c.table_name AND e.column_name=c.column_name WHERE c.table_schema='__SOURCE_SCHEMA__' AND c.table_name IN ('operations_audit','operations_file_delivery') AND e.column_name IS NULL;
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_operations_columns e LEFT JOIN information_schema.columns c ON c.table_schema='__SOURCE_SCHEMA__' AND c.table_name=e.table_name AND c.column_name=e.column_name WHERE c.column_name IS NULL OR NOT(BINARY LOWER(c.column_type)<=>BINARY e.column_type) OR NOT(c.is_nullable<=>e.nullable) OR NOT(c.collation_name<=>e.collation_name) OR NOT(LOWER(c.column_default)<=>e.default_value) OR NOT(LOWER(c.extra)<=>e.extra) OR c.generation_expression<>'';
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.triggers WHERE event_object_schema='__SOURCE_SCHEMA__' AND event_object_table IN ('operations_audit','operations_file_delivery');
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.table_constraints WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('operations_audit','operations_file_delivery') AND constraint_type IN ('FOREIGN KEY','CHECK');
INSERT INTO compact_operations_unique_keys VALUES ('operations_audit',TRUE,'id'),('operations_audit',FALSE,'actor_user_id,domain,action,resource_id,request_id,result'),('operations_file_delivery',TRUE,'id'),('operations_file_delivery',FALSE,'delivery_id');
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM (SELECT table_name,(index_name='PRIMARY') AS primary_key,GROUP_CONCAT(column_name ORDER BY seq_in_index) AS key_columns,SUM(sub_part IS NOT NULL) AS prefixes FROM information_schema.statistics WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('operations_audit','operations_file_delivery') AND non_unique=0 GROUP BY table_name,index_name) a LEFT JOIN compact_operations_unique_keys e ON e.table_name=a.table_name AND e.primary_key=a.primary_key AND e.key_columns=a.key_columns WHERE e.table_name IS NULL OR a.prefixes<>0;
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_operations_unique_keys e LEFT JOIN (SELECT table_name,(index_name='PRIMARY') AS primary_key,GROUP_CONCAT(column_name ORDER BY seq_in_index) AS key_columns,SUM(sub_part IS NOT NULL) AS prefixes FROM information_schema.statistics WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('operations_audit','operations_file_delivery') AND non_unique=0 GROUP BY table_name,index_name) a ON e.table_name=a.table_name AND e.primary_key=a.primary_key AND e.key_columns=a.key_columns WHERE a.table_name IS NULL;
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM audit_event WHERE kind='OPERATIONS' OR legacy_source='operations_audit';
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM workflow_instance WHERE kind='FILE_DELIVERY' OR legacy_source='operations_file_delivery';
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.`operations_audit` s WHERE (s.actor_user_id<=0) OR (BINARY s.scope NOT IN (BINARY 'PRIVATE',BINARY 'ENTERPRISE')) OR (CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00') IS NULL OR NOT(TIMESTAMPDIFF(MICROSECOND,CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00'),s.created_at)<=>((IF(LEFT('__SOURCE_OPERATIONS_OFFSET__',1)='-',-1,1)*(CAST(SUBSTRING('__SOURCE_OPERATIONS_OFFSET__',2,2) AS UNSIGNED)*3600+CAST(SUBSTRING('__SOURCE_OPERATIONS_OFFSET__',5,2) AS UNSIGNED)*60))*1000000))) OR ((s.domain IS NOT NULL AND (CHAR_LENGTH(s.domain)=0 OR REGEXP_LIKE(s.domain,'[^A-Za-z0-9_:./-]','c')))) OR ((s.resource_id IS NOT NULL AND (CHAR_LENGTH(s.resource_id)=0 OR REGEXP_LIKE(s.resource_id,'[^A-Za-z0-9_:./-]','c')))) OR ((s.action IS NOT NULL AND (CHAR_LENGTH(s.action)=0 OR REGEXP_LIKE(s.action,'[^A-Za-z0-9_:./-]','c')))) OR ((s.request_id IS NOT NULL AND (CHAR_LENGTH(s.request_id)=0 OR REGEXP_LIKE(s.request_id,'[^A-Za-z0-9_:./-]','c')))) OR ((s.result IS NOT NULL AND (CHAR_LENGTH(s.result)=0 OR REGEXP_LIKE(s.result,'[^A-Za-z0-9_:./-]','c'))));
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.`operations_file_delivery` s WHERE (s.actor_user_id<=0) OR (BINARY s.scope NOT IN (BINARY 'PRIVATE',BINARY 'ENTERPRISE')) OR (CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00') IS NULL OR NOT(TIMESTAMPDIFF(MICROSECOND,CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00'),s.created_at)<=>((IF(LEFT('__SOURCE_OPERATIONS_OFFSET__',1)='-',-1,1)*(CAST(SUBSTRING('__SOURCE_OPERATIONS_OFFSET__',2,2) AS UNSIGNED)*3600+CAST(SUBSTRING('__SOURCE_OPERATIONS_OFFSET__',5,2) AS UNSIGNED)*60))*1000000))) OR ((s.domain IS NOT NULL AND (CHAR_LENGTH(s.domain)=0 OR REGEXP_LIKE(s.domain,'[^A-Za-z0-9_:./-]','c')))) OR ((s.resource_id IS NOT NULL AND (CHAR_LENGTH(s.resource_id)=0 OR REGEXP_LIKE(s.resource_id,'[^A-Za-z0-9_:./-]','c')))) OR ((s.file_id IS NOT NULL AND (CHAR_LENGTH(s.file_id)=0 OR REGEXP_LIKE(s.file_id,'[^A-Za-z0-9_:./-]','c')))) OR ((s.correlation_id IS NOT NULL AND (CHAR_LENGTH(s.correlation_id)=0 OR REGEXP_LIKE(s.correlation_id,'[^A-Za-z0-9_:./-]','c')))) OR (NOT REGEXP_LIKE(s.delivery_id,'^[a-fA-F0-9]{8}(-[a-fA-F0-9]{4}){3}-[a-fA-F0-9]{12}$','c')) OR (s.revision<0) OR (s.expected_bytes<0) OR (s.accepted_bytes_lower_bound<0) OR (s.http_status IS NOT NULL AND (s.http_status<100 OR s.http_status>599)) OR (BINARY s.state NOT IN (BINARY 'AUTHORIZED',BINARY 'HEAD_AUTHORIZED',BINARY 'STREAMING',BINARY 'UNKNOWN',BINARY 'SERVER_COMPLETED',BINARY 'HEAD_COMPLETED',BINARY 'INTERRUPTED',BINARY 'REDIRECT_AUTHORIZED')) OR (CONVERT_TZ(s.updated_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00') IS NULL OR NOT(TIMESTAMPDIFF(MICROSECOND,CONVERT_TZ(s.updated_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00'),s.updated_at)<=>((IF(LEFT('__SOURCE_OPERATIONS_OFFSET__',1)='-',-1,1)*(CAST(SUBSTRING('__SOURCE_OPERATIONS_OFFSET__',2,2) AS UNSIGNED)*3600+CAST(SUBSTRING('__SOURCE_OPERATIONS_OFFSET__',5,2) AS UNSIGNED)*60))*1000000)));
INSERT INTO audit_event(event_id,kind,owner_user_id,actor_user_id,resource_type,resource_id,request_id,action,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-operations-',s.id),'OPERATIONS',s.actor_user_id,s.actor_user_id,'OPERATIONS',s.resource_id,s.request_id,s.action,CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00'),1,JSON_OBJECT('scope',s.scope,'domain',s.domain,'result',s.result,'resourceVersion',s.resource_version,'legacyId',CAST(s.id AS CHAR),'legacyCreatedAt',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f')),'operations_audit',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.operations_audit s ORDER BY s.id;
INSERT INTO workflow_instance(workflow_id,kind,idempotency_scope,request_id,request_sha256,owner_user_id,actor_user_id,resource_type,resource_id,status,revision,payload_version,payload_json,created_at,updated_at,finished_at,legacy_source,legacy_key) SELECT s.delivery_id,'FILE_DELIVERY','FILE_DELIVERY',s.delivery_id,SHA2(CONCAT_WS(CHAR(10),CAST(s.actor_user_id AS CHAR),s.scope,s.domain,s.resource_id,COALESCE(s.file_id,'~'),s.correlation_id,COALESCE(CAST(s.resource_version AS CHAR),'~'),COALESCE(CAST(s.expected_bytes AS CHAR),'~'),CASE WHEN s.state IN ('AUTHORIZED','STREAMING','SERVER_COMPLETED') THEN 'BODY' WHEN s.state IN ('HEAD_AUTHORIZED','HEAD_COMPLETED') THEN 'HEAD' WHEN s.state='REDIRECT_AUTHORIZED' THEN 'REDIRECT' ELSE 'UNKNOWN' END),256),s.actor_user_id,s.actor_user_id,'FILE_DELIVERY',s.resource_id,s.state,s.revision,1,JSON_OBJECT('scope',s.scope,'domain',s.domain,'fileId',s.file_id,'correlationId',s.correlation_id,'resourceVersion',s.resource_version,'expectedBytes',s.expected_bytes,'acceptedBytesLowerBound',s.accepted_bytes_lower_bound,'httpStatus',s.http_status,'deliveryMode',CASE WHEN s.state IN ('AUTHORIZED','STREAMING','SERVER_COMPLETED') THEN 'BODY' WHEN s.state IN ('HEAD_AUTHORIZED','HEAD_COMPLETED') THEN 'HEAD' WHEN s.state='REDIRECT_AUTHORIZED' THEN 'REDIRECT' ELSE 'UNKNOWN' END,'legacyId',CAST(s.id AS CHAR),'legacyCreatedAt',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'legacyUpdatedAt',DATE_FORMAT(s.updated_at,'%Y-%m-%d %H:%i:%s.%f')),CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00'),CONVERT_TZ(s.updated_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00'),CASE WHEN s.state IN ('SERVER_COMPLETED','HEAD_COMPLETED','INTERRUPTED','REDIRECT_AUTHORIZED') THEN CONVERT_TZ(s.updated_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00') ELSE NULL END,'operations_file_delivery',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.operations_file_delivery s ORDER BY s.id;
INSERT INTO compact_operations_guard SELECT IF((SELECT COUNT(*) FROM audit_event WHERE kind='OPERATIONS')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.operations_audit),1,0);
INSERT INTO compact_operations_guard SELECT IF((SELECT COUNT(*) FROM workflow_instance WHERE kind='FILE_DELIVERY')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.operations_file_delivery),1,0);
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.operations_audit s LEFT JOIN audit_event t ON BINARY t.legacy_source=BINARY 'operations_audit' AND BINARY t.legacy_key=BINARY CAST(s.id AS CHAR) WHERE t.id IS NULL OR NOT(BINARY t.legacy_source<=>BINARY 'operations_audit') OR NOT(BINARY t.legacy_key<=>BINARY CAST(s.id AS CHAR)) OR NOT(BINARY t.kind<=>BINARY 'OPERATIONS') OR NOT(BINARY t.event_id<=>BINARY CONCAT('legacy-operations-',s.id)) OR NOT(t.owner_user_id<=>s.actor_user_id) OR NOT(t.actor_user_id<=>s.actor_user_id) OR NOT(BINARY t.resource_type<=>BINARY 'OPERATIONS') OR NOT(BINARY t.resource_id<=>BINARY s.resource_id) OR NOT(BINARY t.request_id<=>BINARY s.request_id) OR NOT(BINARY t.action<=>BINARY s.action) OR NOT(t.revision IS NULL) OR NOT(t.request_scope IS NULL) OR NOT(t.payload_version<=>1) OR NOT(BINARY t.payload_json<=>BINARY JSON_OBJECT('scope',s.scope,'domain',s.domain,'result',s.result,'resourceVersion',s.resource_version,'legacyId',CAST(s.id AS CHAR),'legacyCreatedAt',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'))) OR NOT(t.occurred_at<=>CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00')) OR NOT(t.detection_model_id IS NULL) OR NOT(t.session_id IS NULL) OR NOT(t.message_id IS NULL) OR NOT(t.run_id IS NULL) OR NOT(t.journal_run_id IS NULL) OR NOT(t.sequence_no IS NULL) OR NOT(t.content_sha256 IS NULL) OR NOT(t.previous_sha256 IS NULL) OR NOT(t.event_sha256 IS NULL) OR NOT(t.quantity IS NULL) OR NOT(t.unit IS NULL) OR NOT(t.policy_version IS NULL) OR NOT(t.outcome IS NULL) OR NOT(t.observed_at IS NULL) OR NOT(t.call_id IS NULL) OR NOT(t.digest_legacy_detail_json IS NULL);
INSERT INTO compact_operations_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.operations_file_delivery s LEFT JOIN workflow_instance t ON BINARY t.legacy_source=BINARY 'operations_file_delivery' AND BINARY t.legacy_key=BINARY CAST(s.id AS CHAR) WHERE t.id IS NULL OR NOT(BINARY t.legacy_source<=>BINARY 'operations_file_delivery') OR NOT(BINARY t.legacy_key<=>BINARY CAST(s.id AS CHAR)) OR NOT(BINARY t.kind<=>BINARY 'FILE_DELIVERY') OR NOT(BINARY t.workflow_id<=>BINARY s.delivery_id) OR NOT(BINARY t.request_id<=>BINARY s.delivery_id) OR NOT(BINARY t.idempotency_scope<=>BINARY 'FILE_DELIVERY') OR NOT(BINARY t.request_sha256<=>BINARY SHA2(CONCAT_WS(CHAR(10),CAST(s.actor_user_id AS CHAR),s.scope,s.domain,s.resource_id,COALESCE(s.file_id,'~'),s.correlation_id,COALESCE(CAST(s.resource_version AS CHAR),'~'),COALESCE(CAST(s.expected_bytes AS CHAR),'~'),CASE WHEN s.state IN ('AUTHORIZED','STREAMING','SERVER_COMPLETED') THEN 'BODY' WHEN s.state IN ('HEAD_AUTHORIZED','HEAD_COMPLETED') THEN 'HEAD' WHEN s.state='REDIRECT_AUTHORIZED' THEN 'REDIRECT' ELSE 'UNKNOWN' END),256)) OR NOT(t.owner_user_id<=>s.actor_user_id) OR NOT(t.actor_user_id<=>s.actor_user_id) OR NOT(BINARY t.resource_type<=>BINARY 'FILE_DELIVERY') OR NOT(BINARY t.resource_id<=>BINARY s.resource_id) OR NOT(t.resource_revision IS NULL) OR NOT(BINARY t.status<=>BINARY s.state) OR NOT(t.revision<=>s.revision) OR NOT(t.payload_version<=>1) OR NOT(BINARY t.payload_json<=>BINARY JSON_OBJECT('scope',s.scope,'domain',s.domain,'fileId',s.file_id,'correlationId',s.correlation_id,'resourceVersion',s.resource_version,'expectedBytes',s.expected_bytes,'acceptedBytesLowerBound',s.accepted_bytes_lower_bound,'httpStatus',s.http_status,'deliveryMode',CASE WHEN s.state IN ('AUTHORIZED','STREAMING','SERVER_COMPLETED') THEN 'BODY' WHEN s.state IN ('HEAD_AUTHORIZED','HEAD_COMPLETED') THEN 'HEAD' WHEN s.state='REDIRECT_AUTHORIZED' THEN 'REDIRECT' ELSE 'UNKNOWN' END,'legacyId',CAST(s.id AS CHAR),'legacyCreatedAt',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'legacyUpdatedAt',DATE_FORMAT(s.updated_at,'%Y-%m-%d %H:%i:%s.%f'))) OR NOT(t.created_at<=>CONVERT_TZ(s.created_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00')) OR NOT(t.updated_at<=>CONVERT_TZ(s.updated_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00')) OR NOT(t.finished_at<=>CASE WHEN s.state IN ('SERVER_COMPLETED','HEAD_COMPLETED','INTERRUPTED','REDIRECT_AUTHORIZED') THEN CONVERT_TZ(s.updated_at,'__SOURCE_OPERATIONS_OFFSET__','+00:00') ELSE NULL END) OR NOT(t.claim_token IS NULL) OR NOT(t.lease_expires_at IS NULL) OR NOT(t.expires_at IS NULL) OR NOT(t.parent_workflow_id IS NULL) OR NOT(t.session_id IS NULL) OR NOT(t.run_id IS NULL) OR NOT(t.fence<=>0) OR NOT(t.attempts<=>0) OR NOT(t.requested_tokens IS NULL) OR NOT(t.decider_user_id IS NULL) OR NOT(t.chat_action_session_id IS NULL) OR NOT(t.confirmation_recorded_at IS NULL) OR NOT(t.active_slot IS NULL) OR NOT(t.effective_date IS NULL) OR NOT(t.scheduled_for IS NULL) OR NOT(t.error_code IS NULL) OR NOT(t.next_attempt_at IS NULL) OR NOT(t.execution_state IS NULL) OR NOT(t.reserved_bytes IS NULL) OR NOT(t.exit_verified IS NULL) OR NOT(t.execution_deadline IS NULL) OR NOT(t.result_version IS NULL) OR NOT(t.result_json IS NULL) OR NOT(t.result_sha256 IS NULL) OR NOT(t.call_id IS NULL) OR NOT(t.mcp_installation_id IS NULL) OR NOT(t.mcp_prior_installation_id IS NULL) OR NOT(t.mcp_owner_username IS NULL) OR NOT(t.mcp_runtime_sha256 IS NULL) OR NOT(t.mcp_pool_id IS NULL) OR NOT(t.mcp_purpose IS NULL) OR NOT(t.mcp_transport IS NULL) OR NOT(t.mcp_image_id IS NULL) OR NOT(t.mcp_exit_verified IS NULL) OR NOT(t.mcp_cleanup_confirmed IS NULL) OR NOT(t.mcp_worker_token IS NULL) OR NOT(t.mcp_writer_exit_verified IS NULL) OR NOT(t.mcp_retained_for_rollback IS NULL) OR NOT(t.mcp_package_version IS NULL) OR NOT(t.mcp_manifest_json IS NULL) OR NOT(t.mcp_manifest_sha256 IS NULL) OR NOT(t.mcp_cleanup_request IS NULL) OR NOT(t.mcp_cleanup_expires_at IS NULL) OR NOT(t.mcp_reconcile_request IS NULL) OR NOT(t.mcp_reconcile_expires_at IS NULL) OR NOT(t.mcp_writer_evidence_code IS NULL) OR NOT(t.mcp_node_sha256 IS NULL) OR NOT(t.mcp_controller_pid IS NULL) OR NOT(t.mcp_controller_started IS NULL) OR NOT(t.mcp_container_id IS NULL) OR NOT(t.mcp_container_started IS NULL) OR NOT(t.mcp_controller_pool_id IS NULL) OR NOT(t.mcp_native_pool_id IS NULL) OR NOT(t.mcp_action IS NULL) OR NOT(t.mcp_retention_protocol IS NULL) OR NOT(t.mcp_source_created_at IS NULL) OR NOT(t.mcp_source_updated_at IS NULL) OR NOT(t.mcp_source_utc_offset IS NULL) OR NOT(t.digest_legacy_row_json IS NULL);
