-- Operations/file delivery copy candidate, NOT EXECUTED. Source is actual V40/V52 DDL, not renamed target DDL.
-- Use distinct, stopped source/target schemas; render source identifier and the evidenced fixed source UTC offset explicitly.
-- Target public DDL must already exist, with empty OPERATIONS/FILE_DELIVERY kinds. Other domains may already be copied.
-- Stop at the first error and ROLLBACK on this same connection. Never --force. No source UPDATE/DELETE/DROP.
-- Shared target IDs are new cursor identities; original IDs and DATETIME(6) strings remain in payload + legacy provenance.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE compact_operations_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_operations_columns(table_name VARCHAR(64),column_name VARCHAR(64),column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(table_name,column_name)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_operations_unique_keys(table_name VARCHAR(64),primary_key BOOLEAN,key_columns VARCHAR(1024)) ENGINE=InnoDB;
START TRANSACTION;
COMMIT;
DROP TEMPORARY TABLE compact_operations_unique_keys;
DROP TEMPORARY TABLE compact_operations_columns;
DROP TEMPORARY TABLE compact_operations_guard;
